using Wip.Bones.Domain;
using Wip.Bones.Engine;
using System.Collections.Generic;
using System.Linq;

public sealed class SeatStrategy : IBonesPlayerSlot
{
    public BonesMove ChooseMove(BonesRoundState state, IReadOnlyList<BonesMove> legalMoves)
    {
        if (legalMoves.Count == 0)
            throw new System.InvalidOperationException("No legal moves.");

        var nonPassMoves = legalMoves.Where(m => !m.IsPass).ToList();
        if (nonPassMoves.Count == 0)
            return legalMoves[0];

        var board = state.Board;
        var hand = state.Hands.GetHand(state.CurrentPlayer);
        int leftEndPip = board.LeftEnd?.Pip.Value ?? -1;
        int rightEndPip = board.RightEnd?.Pip.Value ?? -1;

        // Count pip frequencies in hand
        int[] pipCounts = new int[7];
        foreach (var t in hand.Tiles)
        {
            pipCounts[t.LowPip.Value]++;
            if (!t.IsDouble)
                pipCounts[t.HighPip.Value]++;
        }

        // Count total pips in hand for endgame awareness
        int handTotalPips = 0;
        foreach (var t in hand.Tiles)
            handTotalPips += t.TotalPips;

        int handTileCount = hand.Tiles.Length;
        bool isEndgame = handTileCount <= 3;

        // Global pip counts from board tiles
        int[] globalPipCounts = new int[7];
        foreach (var chainTile in board.Tiles)
        {
            globalPipCounts[chainTile.Tile.LowPip.Value]++;
            if (!chainTile.Tile.IsDouble)
                globalPipCounts[chainTile.Tile.HighPip.Value]++;
        }

        // Estimate opponent pip counts
        int[] opponentPipCounts = new int[7];
        for (int i = 0; i < 7; i++)
        {
            opponentPipCounts[i] = 28 - globalPipCounts[i] - pipCounts[i];
            if (opponentPipCounts[i] < 0) opponentPipCounts[i] = 0;
        }

        BonesMove? bestMove = null;
        int bestScore = int.MinValue;

        foreach (var move in nonPassMoves)
        {
            var tile = move.Tile!.Value;
            int score = 0;

            // Strong value for doubles - they control board and reduce hand options for opponents
            if (tile.IsDouble)
                score += 70;

            // Prefer high pip tiles to shed large tiles
            score += tile.TotalPips * 4;

            bool matchesLeft = leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip);
            bool matchesRight = rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip);

            if (matchesLeft || matchesRight)
                score += 80;
            else
                score -= 60;

            // Avoid playing a tile that would leave us with no matching ends (risk of being blocked)
            int remainingMatching = 0;
            if (leftEndPip >= 0 || rightEndPip >= 0)
            {
                remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 0)
                    score -= 150; // Heavy penalty for leaving no options
            }

            // Prefer playing on side matching our stronger pip holdings
            if (matchesLeft)
            {
                int leftPipCount = pipCounts[leftEndPip];
                score += leftPipCount * 8;
                if (move.Side == BonesBoardSide.Left)
                    score += 20;
            }
            if (matchesRight)
            {
                int rightPipCount = pipCounts[rightEndPip];
                score += rightPipCount * 8;
                if (move.Side == BonesBoardSide.Right)
                    score += 20;
            }

            // Bonus for playing tiles that match pips we have many of (future options)
            int lowPipCount = pipCounts[tile.LowPip.Value];
            int highPipCount = tile.IsDouble ? 0 : pipCounts[tile.HighPip.Value];
            score += (lowPipCount + highPipCount) * 6;

            // Penalty for playing a double when we have many of that pip (risk of being stuck)
            if (tile.IsDouble)
            {
                int otherPip = tile.LowPip.Value;
                if (pipCounts[otherPip] >= 3)
                    score -= 40;
            }

            // Prefer playing on side with fewer chain tiles to maintain balance
            if (matchesLeft && matchesRight)
            {
                int leftChainCount = 0, rightChainCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip)
                        leftChainCount++;
                    if (chainTile.ChainRightPip.Value == rightEndPip)
                        rightChainCount++;
                }
                if (leftChainCount < rightChainCount && move.Side == BonesBoardSide.Left)
                    score += 30;
                else if (rightChainCount < leftChainCount && move.Side == BonesBoardSide.Right)
                    score += 30;
                else if (leftChainCount == rightChainCount)
                    score += 15;
            }

            // Endgame awareness: prefer playing high pip tiles when hand total is low
            if (handTotalPips <= 20)
                score += tile.TotalPips * 3;

            // Additional endgame bonus: when hand is small, prefer playing tiles that match our strong suits
            if (isEndgame)
            {
                // In endgame, prefer playing doubles to block opponents
                if (tile.IsDouble)
                    score += 50;
                // Also prefer playing tiles that keep us from being blocked
                if (remainingMatching > 0)
                    score += 40;
                // Penalty for playing a tile that matches opponent's strong pip
                int opponentLowPips = opponentPipCounts[tile.LowPip.Value];
                int opponentHighPips = tile.IsDouble ? 0 : opponentPipCounts[tile.HighPip.Value];
                if (opponentLowPips + opponentHighPips >= 4)
                    score -= 30;
            }

            // Bonus for playing tiles that match pips opponents are weak in (strategic blocking)
            int oppLowPips = opponentPipCounts[tile.LowPip.Value];
            int oppHighPips = tile.IsDouble ? 0 : opponentPipCounts[tile.HighPip.Value];
            if (oppLowPips + oppHighPips <= 1)
                score += 25;

            // Track best move
            if (score > bestScore)
            {
                bestScore = score;
                bestMove = move;
            }
        }

        return bestMove ?? nonPassMoves[0];
    }

    private int CountMatchingAfterPlay(BonesHand hand, BonesTile playedTile, int leftEndPip, int rightEndPip)
    {
        int count = 0;
        foreach (var tile in hand.Tiles)
        {
            if (tile.Equals(playedTile))
                continue;
            if (leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip))
                count++;
            if (rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip))
                count++;
        }
        return count;
    }
}
